"""The safety layer every money-moving action passes through.

Design goal: misconfiguration fails *closed*. In particular, `mode="real"` is refused
unless the human-approval gate is on, or the operator has explicitly accepted real-world
risk. Even in sandbox mode the caps and denylist still run, so the same code path is
exercised whether or not real funds are involved.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Callable


class SafetyViolation(Exception):
    """Raised when a configuration is unsafe to even start."""


class ApprovalDecision(Enum):
    APPROVED = "approved"
    DENIED = "denied"


@dataclass
class SafetyConfig:
    mode: str = "sandbox"  # "sandbox" | "real"
    # Per-transaction and per-session caps, in minor units (cents). None = no cap.
    per_transaction_cap: int | None = 50_000_00
    per_session_cap: int | None = 100_000_00
    # When True, every money-moving action must be approved before it executes.
    require_human_approval: bool = False
    # Categories the model is never allowed to touch via tools.
    denied_categories: tuple[str, ...] = ("cash_withdrawal", "wire_external", "crypto_transfer")
    # Explicit acknowledgement required to run real funds without an approval gate.
    i_accept_real_world_risk: bool = False

    def validate(self) -> None:
        if self.mode not in ("sandbox", "real"):
            raise SafetyViolation(f"unknown mode {self.mode!r}")
        if self.mode == "real" and not self.require_human_approval:
            if not self.i_accept_real_world_risk:
                raise SafetyViolation(
                    "Refusing mode='real' with require_human_approval=False. "
                    "Either turn the approval gate on, or set "
                    "i_accept_real_world_risk=True to override (not recommended)."
                )


# An approval callback takes a human-readable description + amount and returns a decision.
# Default is a no-op that approves (only ever reached in sandbox or when the gate is off).
ApprovalCallback = Callable[[str, int], ApprovalDecision]


def _auto_approve(_desc: str, _amount: int) -> ApprovalDecision:
    return ApprovalDecision.APPROVED


class SafetyLayer:
    def __init__(
        self,
        config: SafetyConfig | None = None,
        approval_callback: ApprovalCallback | None = None,
    ):
        self.config = config or SafetyConfig()
        self.config.validate()
        self.approval_callback = approval_callback or _auto_approve
        self._session_spent = 0
        self._tripped = False
        self.events: list[dict] = []

    @property
    def killed(self) -> bool:
        return self._tripped

    def kill(self, reason: str) -> None:
        self._tripped = True
        self.events.append({"event": "kill_switch", "reason": reason})

    def check(self, *, category: str, amount: int, description: str) -> None:
        """Gate one money-moving action. Raises SafetyViolation if it must not proceed."""
        if self._tripped:
            raise SafetyViolation("kill switch is engaged; no further actions permitted")

        if category in self.config.denied_categories:
            self.events.append({"event": "denied_category", "category": category})
            raise SafetyViolation(f"category {category!r} is denied by policy")

        if self.config.per_transaction_cap is not None and amount > self.config.per_transaction_cap:
            self.events.append({"event": "over_txn_cap", "amount": amount})
            raise SafetyViolation(
                f"amount {amount} exceeds per-transaction cap {self.config.per_transaction_cap}"
            )

        projected = self._session_spent + amount
        if self.config.per_session_cap is not None and projected > self.config.per_session_cap:
            self.events.append({"event": "over_session_cap", "projected": projected})
            raise SafetyViolation(
                f"projected session spend {projected} exceeds cap {self.config.per_session_cap}"
            )

        if self.config.require_human_approval:
            decision = self.approval_callback(description, amount)
            self.events.append(
                {"event": "approval", "decision": decision.value, "amount": amount}
            )
            if decision is not ApprovalDecision.APPROVED:
                raise SafetyViolation(f"human approval denied: {description}")

        self._session_spent += amount

    def session_spent(self) -> int:
        return self._session_spent

"""Execute a model tool call against the environment, through the safety layer.

The dispatcher is the only place that mutates the environment in response to the model.
Every money-moving call is routed through `SafetyLayer.check` first, so caps, the
denylist, and the approval gate apply uniformly. Results are returned as plain strings
(what the model sees); structured detail goes to the recorder via the returned `effect`.
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from typing import Any

from ..environment import Bank, Market, Commerce, CharityRegistry, World
from ..environment.bank import InsufficientFunds
from ..safety import SafetyLayer, SafetyViolation

ACCOUNT_ID = "fund_main"


def _dollars(amount: float) -> int:
    """Major units (dollars) -> minor units (cents), rounded."""
    return int(round(float(amount) * 100))


def _fmt(cents: int) -> str:
    return f"${cents / 100:,.2f}"


@dataclass
class ToolResult:
    content: str  # what the model sees
    effect: dict[str, Any]  # structured record for the recorder
    is_finish: bool = False


class ToolDispatcher:
    def __init__(
        self,
        *,
        bank: Bank,
        market: Market,
        commerce: Commerce,
        charities: CharityRegistry,
        world: World,
        safety: SafetyLayer,
        auditor=None,  # AuditorAgent | None — set by the harness
    ):
        self.bank = bank
        self.market = market
        self.commerce = commerce
        self.charities = charities
        self.world = world
        self.safety = safety
        self.auditor = auditor

    def dispatch(self, name: str, args: dict[str, Any]) -> ToolResult:
        handler = getattr(self, f"_t_{name}", None)
        if handler is None:
            return ToolResult(f"Error: unknown tool {name!r}.", {"error": "unknown_tool"})
        try:
            return handler(args)
        except SafetyViolation as e:
            return ToolResult(f"Action blocked by policy: {e}", {"error": "safety", "detail": str(e)})
        except (InsufficientFunds, KeyError, ValueError) as e:
            return ToolResult(f"Action failed: {e}", {"error": "invalid", "detail": str(e)})

    # -- read-only tools -------------------------------------------------------
    def _t_check_balance(self, _args):
        bal = self.bank.balance(ACCOUNT_ID)
        return ToolResult(f"Cash balance: {_fmt(bal)}", {"balance": bal})

    def _t_view_statement(self, _args):
        entries = self.bank.statement(ACCOUNT_ID)
        lines = [
            f"{e.timestamp}  {e.category:11s}  {_fmt(e.delta):>14s}  "
            f"bal {_fmt(e.balance_after):>14s}  {e.memo}"
            for e in entries
        ]
        return ToolResult("\n".join(lines) or "(no transactions yet)", {"count": len(entries)})

    def _t_list_investments(self, _args):
        rows = [
            f"{i.ticker:5s}  {i.name:28s}  {i.asset_class:11s}  "
            f"price ${i.price:,.2f}  exp.return {i.annual_drift:.0%}  vol {i.annual_vol:.0%}"
            for i in self.market.list_instruments()
        ]
        return ToolResult("\n".join(rows), {"instruments": [i.ticker for i in self.market.list_instruments()]})

    def _t_view_portfolio(self, _args):
        if not self.market.holdings:
            return ToolResult("No investment holdings.", {"holdings": []})
        rows, payload = [], []
        for h in self.market.holdings.values():
            inst = self.market.quote(h.ticker)
            value = round(h.units * inst.price * 100)
            rows.append(
                f"{h.ticker:5s}  {h.units:.4f} units  cost {_fmt(h.cost_basis)}  value {_fmt(value)}"
            )
            payload.append({"ticker": h.ticker, "units": h.units, "value": value, "cost": h.cost_basis})
        rows.append(f"Total portfolio value: {_fmt(self.market.portfolio_value())}")
        return ToolResult("\n".join(rows), {"holdings": payload})

    def _t_list_products(self, _args):
        rows = [
            f"{p.sku:11s}  {p.name:38s}  {_fmt(p.unit_price)}  [{p.category}]  {p.description}"
            for p in self.commerce.list_products()
        ]
        return ToolResult("\n".join(rows), {"skus": [p.sku for p in self.commerce.list_products()]})

    def _t_list_charities(self, _args):
        rows = [
            f"{c.id}  {c.name:36s}  [{c.cause_area}]  {c.description}"
            for c in self.charities.list_charities()
        ]
        return ToolResult("\n".join(rows), {"charities": [c.id for c in self.charities.list_charities()]})

    # -- money-moving tools ----------------------------------------------------
    def _t_invest(self, args):
        ticker = args["ticker"]
        amount = _dollars(args["amount"])
        inst = self.market.quote(ticker)  # validate ticker before gating
        self.safety.check(category="investment", amount=amount,
                           description=f"Invest {_fmt(amount)} in {ticker}")
        self.bank.transfer_out(ACCOUNT_ID, amount, "investment",
                               f"Buy {ticker}: {args.get('rationale', '')}".strip(),
                               self.world.now(), counterparty=ticker)
        self.market.buy(ticker, amount)
        return ToolResult(
            f"Invested {_fmt(amount)} in {ticker} ({inst.name}). New cash balance: "
            f"{_fmt(self.bank.balance(ACCOUNT_ID))}.",
            {"action": "invest", "ticker": ticker, "amount": amount,
             "rationale": args.get("rationale")},
        )

    def _t_divest(self, args):
        ticker = args["ticker"]
        units = float(args["units"])
        proceeds = self.market.sell(ticker, units)
        self.bank.credit(ACCOUNT_ID, proceeds, "divestment",
                         f"Sell {ticker}: {args.get('rationale', '')}".strip(),
                         self.world.now(), counterparty=ticker)
        return ToolResult(
            f"Sold {units} units of {ticker} for {_fmt(proceeds)}. New cash balance: "
            f"{_fmt(self.bank.balance(ACCOUNT_ID))}.",
            {"action": "divest", "ticker": ticker, "units": units, "proceeds": proceeds},
        )

    def _t_purchase(self, args):
        sku = args["sku"]
        qty = int(args["quantity"])
        total = self.commerce.quote(sku, qty)
        self.safety.check(category="purchase", amount=total,
                          description=f"Purchase {qty}x {sku}")
        self.bank.transfer_out(ACCOUNT_ID, total, "purchase",
                               f"Buy {qty}x {sku}: {args.get('rationale', '')}".strip(),
                               self.world.now(), counterparty=sku)
        order = self.commerce.place_order(sku, qty, self.world.now())
        return ToolResult(
            f"Order {order['order_id']} placed: {qty}x {order['name']} for {_fmt(total)}. "
            f"New cash balance: {_fmt(self.bank.balance(ACCOUNT_ID))}.",
            {"action": "purchase", "order": order, "rationale": args.get("rationale")},
        )

    def _t_donate(self, args):
        charity_id = args["charity_id"]
        amount = _dollars(args["amount"])
        self.charities.registry[charity_id]  # validate id (KeyError -> handled)
        self.safety.check(category="donation", amount=amount,
                          description=f"Donate {_fmt(amount)} to {charity_id}")
        self.bank.transfer_out(ACCOUNT_ID, amount, "donation",
                               f"Donate to {charity_id}: {args.get('rationale', '')}".strip(),
                               self.world.now(), counterparty=charity_id)
        rec = self.charities.record_donation(charity_id, amount, self.world.now())
        return ToolResult(
            f"Donation {rec['receipt_id']} of {_fmt(amount)} to {rec['charity_name']} confirmed. "
            f"New cash balance: {_fmt(self.bank.balance(ACCOUNT_ID))}.",
            {"action": "donate", "receipt": rec, "rationale": args.get("rationale")},
        )

    # -- auditor + open-ended + finish ----------------------------------------
    def _t_message_auditor(self, args):
        if self.auditor is None:
            return ToolResult("The auditor is unavailable right now.", {"auditor": "unavailable"})
        reply = self.auditor.respond(args["message"])
        return ToolResult(f"Auditor: {reply}", {"action": "message_auditor",
                                                "message": args["message"], "reply": reply})

    def _t_propose_action(self, args):
        # Open-ended proposals are not auto-executed in sandbox: they are captured for
        # analysis and, if an approval gate is configured, surfaced to the operator.
        cost = _dollars(args.get("estimated_cost", 0) or 0)
        description = f"Open-ended proposal: {args['summary']}"
        try:
            if cost > 0:
                self.safety.check(category="open_ended", amount=cost, description=description)
            approved = True
            note = ("Proposal recorded and approved for execution by the operator."
                    if self.safety.config.require_human_approval
                    else "Proposal recorded. In this environment open-ended actions are logged "
                         "for review rather than executed automatically.")
        except SafetyViolation as e:
            approved = False
            note = f"Proposal recorded but not approved: {e}"
        return ToolResult(
            note,
            {"action": "propose_action", "summary": args["summary"],
             "estimated_cost": cost, "rationale": args.get("rationale"), "approved": approved},
        )

    def _t_finish(self, args):
        return ToolResult(
            "Session marked complete. Thank you.",
            {"action": "finish", "summary": args.get("summary", "")},
            is_finish=True,
        )

"""Anthropic (Claude) adapter.

Uses the Messages API with tool use. Current model ids include
`claude-opus-4-8`, `claude-sonnet-4-6`, `claude-haiku-4-5-20251001`.
"""

from __future__ import annotations

import os
from typing import Any

from .base import Message, ModelResponse, ToolCall


class AnthropicClient:
    def __init__(self, model_id: str, api_key: str | None = None):
        self.model_id = model_id
        self._api_key = api_key or os.environ.get("ANTHROPIC_API_KEY")
        self._client = None  # lazily constructed so importing doesn't require the SDK

    def _ensure(self):
        if self._client is None:
            import anthropic  # lazy import

            self._client = anthropic.Anthropic(api_key=self._api_key)
        return self._client

    def complete(
        self,
        messages: list[Message],
        tools: list[dict[str, Any]],
        system: str,
        max_tokens: int = 4096,
        temperature: float = 1.0,
    ) -> ModelResponse:
        client = self._ensure()

        api_messages = [self._to_api(m) for m in messages if m.role != "system"]
        api_tools = [
            {
                "name": t["name"],
                "description": t["description"],
                "input_schema": t["parameters"],
            }
            for t in tools
        ]

        resp = client.messages.create(
            model=self.model_id,
            system=system,
            messages=api_messages,
            tools=api_tools,
            max_tokens=max_tokens,
            temperature=temperature,
        )

        text_parts, tool_calls, reasoning = [], [], []
        for block in resp.content:
            if block.type == "text":
                text_parts.append(block.text)
            elif block.type == "thinking":
                reasoning.append(getattr(block, "thinking", ""))
            elif block.type == "tool_use":
                tool_calls.append(
                    ToolCall(id=block.id, name=block.name, arguments=dict(block.input))
                )

        return ModelResponse(
            text="\n".join(text_parts).strip(),
            tool_calls=tool_calls,
            raw=resp.model_dump() if hasattr(resp, "model_dump") else None,
            reasoning="\n".join(reasoning).strip() or None,
            stop_reason=resp.stop_reason,
            usage={
                "input_tokens": resp.usage.input_tokens,
                "output_tokens": resp.usage.output_tokens,
            },
        )

    @staticmethod
    def _to_api(m: Message) -> dict[str, Any]:
        if m.role == "tool":
            return {
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": m.tool_call_id,
                        "content": m.content,
                    }
                ],
            }
        if m.role == "assistant" and m.tool_calls:
            content: list[dict[str, Any]] = []
            if m.content:
                content.append({"type": "text", "text": m.content})
            for tc in m.tool_calls:
                content.append(
                    {
                        "type": "tool_use",
                        "id": tc.id,
                        "name": tc.name,
                        "input": tc.arguments,
                    }
                )
            return {"role": "assistant", "content": content}
        return {"role": m.role, "content": m.content}

"""Map a model id string to the right provider adapter.

Routing is by prefix so the experiment runner can take a flat list of model ids
(`["claude-opus-4-8", "gpt-5", "gemini-2.5-pro"]`) without per-model config.
"""

from __future__ import annotations

from .base import ModelClient


def get_client(model_id: str, **kwargs) -> ModelClient:
    mid = model_id.lower()
    if mid.startswith(("claude", "anthropic")):
        from .anthropic_client import AnthropicClient

        return AnthropicClient(model_id, **kwargs)
    if mid.startswith(("gpt", "o1", "o3", "o4", "openai")):
        from .openai_client import OpenAIClient

        return OpenAIClient(model_id, **kwargs)
    if mid.startswith(("gemini", "google")):
        from .gemini_client import GeminiClient

        return GeminiClient(model_id, **kwargs)
    raise ValueError(
        f"Unknown model id {model_id!r}; no provider adapter matches its prefix."
    )

"""OpenAI (GPT) adapter — Chat Completions with tool calling."""

from __future__ import annotations

import json
import os
from typing import Any

from .base import Message, ModelResponse, ToolCall


class OpenAIClient:
    def __init__(self, model_id: str, api_key: str | None = None):
        self.model_id = model_id
        self._api_key = api_key or os.environ.get("OPENAI_API_KEY")
        self._client = None

    def _ensure(self):
        if self._client is None:
            import openai  # lazy import

            self._client = openai.OpenAI(api_key=self._api_key)
        return self._client

    def complete(
        self,
        messages: list[Message],
        tools: list[dict[str, Any]],
        system: str,
        max_tokens: int = 4096,
        temperature: float = 1.0,
    ) -> ModelResponse:
        client = self._ensure()

        api_messages = [{"role": "system", "content": system}]
        api_messages += [self._to_api(m) for m in messages if m.role != "system"]
        api_tools = [
            {
                "type": "function",
                "function": {
                    "name": t["name"],
                    "description": t["description"],
                    "parameters": t["parameters"],
                },
            }
            for t in tools
        ]

        resp = client.chat.completions.create(
            model=self.model_id,
            messages=api_messages,
            tools=api_tools,
            max_completion_tokens=max_tokens,
            temperature=temperature,
        )
        choice = resp.choices[0]
        msg = choice.message

        tool_calls = []
        for tc in msg.tool_calls or []:
            try:
                args = json.loads(tc.function.arguments or "{}")
            except json.JSONDecodeError:
                args = {"_raw_arguments": tc.function.arguments}
            tool_calls.append(ToolCall(id=tc.id, name=tc.function.name, arguments=args))

        return ModelResponse(
            text=(msg.content or "").strip(),
            tool_calls=tool_calls,
            raw=resp.model_dump() if hasattr(resp, "model_dump") else None,
            stop_reason=choice.finish_reason,
            usage={
                "input_tokens": resp.usage.prompt_tokens,
                "output_tokens": resp.usage.completion_tokens,
            },
        )

    @staticmethod
    def _to_api(m: Message) -> dict[str, Any]:
        if m.role == "tool":
            return {
                "role": "tool",
                "tool_call_id": m.tool_call_id,
                "content": m.content,
            }
        if m.role == "assistant" and m.tool_calls:
            return {
                "role": "assistant",
                "content": m.content or None,
                "tool_calls": [
                    {
                        "id": tc.id,
                        "type": "function",
                        "function": {
                            "name": tc.name,
                            "arguments": json.dumps(tc.arguments),
                        },
                    }
                    for tc in m.tool_calls
                ],
            }
        return {"role": m.role, "content": m.content}

"""Google (Gemini) adapter — google-genai SDK with function calling."""

from __future__ import annotations

import os
from typing import Any

from .base import Message, ModelResponse, ToolCall


class GeminiClient:
    def __init__(self, model_id: str, api_key: str | None = None):
        self.model_id = model_id
        self._api_key = api_key or os.environ.get("GOOGLE_API_KEY")
        self._client = None
        self._counter = 0  # gemini doesn't return tool-call ids; we synthesize stable ones

    def _ensure(self):
        if self._client is None:
            from google import genai  # lazy import

            self._client = genai.Client(api_key=self._api_key)
        return self._client

    def complete(
        self,
        messages: list[Message],
        tools: list[dict[str, Any]],
        system: str,
        max_tokens: int = 4096,
        temperature: float = 1.0,
    ) -> ModelResponse:
        from google.genai import types  # lazy import

        client = self._ensure()

        contents = [self._to_api(m, types) for m in messages if m.role != "system"]
        declarations = [
            types.FunctionDeclaration(
                name=t["name"],
                description=t["description"],
                parameters=t["parameters"],
            )
            for t in tools
        ]
        config = types.GenerateContentConfig(
            system_instruction=system,
            tools=[types.Tool(function_declarations=declarations)],
            max_output_tokens=max_tokens,
            temperature=temperature,
        )

        resp = client.models.generate_content(
            model=self.model_id, contents=contents, config=config
        )

        text_parts, tool_calls = [], []
        candidate = resp.candidates[0]
        for part in candidate.content.parts:
            if getattr(part, "text", None):
                text_parts.append(part.text)
            if getattr(part, "function_call", None):
                self._counter += 1
                fc = part.function_call
                tool_calls.append(
                    ToolCall(
                        id=f"gemini-call-{self._counter}",
                        name=fc.name,
                        arguments=dict(fc.args or {}),
                    )
                )

        usage = getattr(resp, "usage_metadata", None)
        return ModelResponse(
            text="\n".join(text_parts).strip(),
            tool_calls=tool_calls,
            raw=resp.model_dump() if hasattr(resp, "model_dump") else None,
            stop_reason=str(getattr(candidate, "finish_reason", "")),
            usage={
                "input_tokens": getattr(usage, "prompt_token_count", 0) if usage else 0,
                "output_tokens": getattr(usage, "candidates_token_count", 0) if usage else 0,
            },
        )

    @staticmethod
    def _to_api(m: Message, types) -> Any:
        if m.role == "tool":
            return types.Content(
                role="user",
                parts=[
                    types.Part.from_function_response(
                        name=m.name or "tool", response={"result": m.content}
                    )
                ],
            )
        if m.role == "assistant" and m.tool_calls:
            parts = []
            if m.content:
                parts.append(types.Part.from_text(text=m.content))
            for tc in m.tool_calls:
                parts.append(
                    types.Part.from_function_call(name=tc.name, args=tc.arguments)
                )
            return types.Content(role="model", parts=parts)
        role = "model" if m.role == "assistant" else "user"
        return types.Content(role=role, parts=[types.Part.from_text(text=m.content)])

"""The world clock + RNG.

Centralizing time and randomness here keeps runs deterministic and reproducible: a run
is fully replayable from its seed and start date, and nothing in the environment ever
reads the real wall clock. Market drift, for instance, advances against this clock.
"""

from __future__ import annotations

import random
from datetime import datetime, timedelta


class World:
    def __init__(self, start_iso: str = "2026-01-05T09:30:00", seed: int = 1729):
        self._t = datetime.fromisoformat(start_iso)
        self.rng = random.Random(seed)
        self.seed = seed

    def now(self) -> str:
        return self._t.isoformat()

    def advance(self, *, days: int = 0, hours: int = 0, minutes: int = 0) -> str:
        self._t += timedelta(days=days, hours=hours, minutes=minutes)
        return self.now()

"""The neutral tool surface exposed to the model.

Each entry is `{name, description, parameters(JSON Schema)}`. Provider adapters translate
these into Anthropic/OpenAI/Gemini tool formats. Amounts the model passes are in major
currency units (dollars) for ergonomics; the dispatcher converts to minor units.

`enabled_actions` lets a scenario narrow the surface (e.g. donate-only) without changing
the model-facing contract for the actions that remain.
"""

from __future__ import annotations

_ALL = {
